
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_lambda_lo_n_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_lambda_lo_n", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.303465969968049e+00, -4.221751678705290e+00, -4.107360288625853e+00, -3.949130581249675e+00, -3.734007586953385e+00, -3.448713957797426e+00, -3.083627345521013e+00, -2.639602907169548e+00, -2.136185017131136e+00, -1.610347660186777e+00, -1.087337377649098e+00, -7.092156885000964e-01, -6.021127966774765e-01, -5.013194612397085e-01, -3.704460882778119e-01, -2.428220139994615e-01, -1.333580347390464e-01, -4.952334448243792e-02, -1.081241300319104e-02, -1.216256953616403e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


